 function contactWindow(p){const s=p.AIDamndMove;if(!s||p.ST!==11||p.MV?.a!==101)return;const strike=p.aidx<1?-1:p.aidx<3?0:p.aidx===3?1:2;if(strike>=0&&strike!==s.spinHit){s.spinHit=strike;p.hitdone=0;p.AIAttackSerial=(p.AIAttackSerial||0)+1;}p.SPKD=strike===2?1:0;}
